<h2><?= $e($settings['heading']??'Projects') ?></h2><div class="project-grid"><?php foreach($items as $item): ?><article class="project-card"><?php if($image($item['main_image_path']??'')): ?><img src="<?= $e($image($item['main_image_path'])) ?>" alt="<?= $e($item['main_image_alt']??$item['title']) ?>" loading="lazy"><?php endif; ?><h3><a href="<?= url('portfolio/'.rawurlencode($item['slug'])) ?>"><?= $e($item['title']) ?></a></h3><p><?= $e($item['short_description']??'') ?></p></article><?php endforeach; ?></div>
